{"code": "import nanosurf, time, os
spm=nanosurf.SPM(); app=spm.application; scan=app.Scan; op=app.OperatingMode
scan.ImageWidth=10e-6; scan.ImageHeight=10e-6; scan.Points=128; scan.Lines=128; scan.Scantime=0.4
try: op.Mode='Tapping'
except: 
    try: op.setMode('Tapping')
    except Exception as e: print('Mode error',e)
scan.Start()
time.sleep(55)
wd=os.getcwd()
files=[os.path.join(wd,f) for f in os.listdir(wd) if f.lower().endswith(('.tif','.tiff','.png','.jpg','.jpeg'))]
print('Files:',files)"}

